    // Get the table with "Number of athletes by National Olympic Committees"
    const tables = document.querySelectorAll('table');
    let targetTable = null;
    for (let table of tables) {
        const caption = table.querySelector('caption');
        if (caption && caption.textContent.includes('Number of athletes')) {
            targetTable = table;
            break;
        }
    }
    if (!targetTable) {
        // Try to find by header
        const headers = document.querySelectorAll('h3');
        for (let header of headers) {
            if (header.textContent.includes('Number of athletes')) {
                targetTable = header.nextElementSibling;
                while (targetTable && targetTable.tagName !== 'TABLE') {
                    targetTable = targetTable.nextElementSibling;
                }
                break;
            }
        }
    }
    if (!targetTable) {
        // Fallback: find table with "Country" and "Athletes" headers
        for (let table of tables) {
            const ths = table.querySelectorAll('th');
            for (let th of ths) {
                if (th.textContent.includes('Country') && th.textContent.includes('Athletes')) {
                    targetTable = table;
                    break;
                }
            }
            if (targetTable) break;
        }
    }

    if (!targetTable) {
        console.error('Table not found');
        return [];
    }

    const rows = targetTable.querySelectorAll('tbody tr');
    const data = [];
    for (let row of rows) {
        const cells = row.querySelectorAll('td');
        if (cells.length >= 2) {
            const countryCell = cells[0];
            const athleteCell = cells[1];
            const countryName = countryCell.textContent.trim();
            const athleteCount = athleteCell.textContent.trim();

            // Skip "Total" row
            if (countryName === 'Total' || countryName === '') continue;

            data.push({
                country: countryName,
                athletes: parseInt(athleteCount.replace(',', '')) || athleteCount,
                iocCode: '' // to be filled later
            });
        }
    }
    return data;
}"}

