  const table = document.querySelector('table');
  if (!table) return null;

  // Find the table with "Country" and "Athletes" headers
  const allTables = document.querySelectorAll('table');
  let targetTable = null;

  for (const t of allTables) {
    const text = t.innerText;
    if (text.includes('Country') && text.includes('Athletes') && text.includes('Germany')) {
      targetTable = t;
      break;
    }
  }

  if (!targetTable) return null;

  // Extract data from table
  const rows = targetTable.querySelectorAll('tr');
  const data = [];

  for (const row of rows) {
    const cells = row.querySelectorAll('td, th');
    if (cells.length >= 2) {
      const countryCell = cells[0];
      const athletesCell = cells[1];

      // Skip header rows
      if (countryCell.textContent.includes('Country') || countryCell.textContent.includes('hide') || countryCell.textContent.includes('show')) {
        continue;
      }

      const country = countryCell.textContent.trim();
      const athletes = athletesCell.textContent.trim();

      if (country && athletes && country !== 'Total') {
        data.push({ country, athletes });
      }
    }
  }

  return data;
}"}

