  for (let i = 0; i < tables.length; i++) {
    const table = tables[i];
    const text = table.innerText;

    // Look for common IOC patterns: 3-letter codes typically in uppercase
    const hasThreeLetterCodes = /\b[A-Z]{3}\b/.test(text);
    // Also look for numbers that could be athlete counts
    const hasNumbers = /\d+\s*athletes?/.test(text.toLowerCase());

    if (hasThreeLetterCodes || hasNumbers) {
      const rows = table.querySelectorAll('tr');
      const rowCount = rows.length;

      // Check if table has reasonable structure
      if (rowCount >= 10 && rowCount <= 60) {
        result.push({
          index: i,
          rowCount,
          preview: text.substring(0, 300),
          hasThreeLetterCodes,
          hasNumbers
        });
      }
    }
  }

  return result;
}"}

